UPDATE `informasi_sertamertas` SET `judul` = 'Perpanjangan Masa Pendaftaran SIPENCATAR Jalur Mandiri Gelombang II PKTJ Tahun Akademik 2026/2027', `deskripsi` = 'Informasi mengenai perpanjangan masa pendaftaran Seleksi Penerimaan Calon Taruna (SIPENCATAR) Jalur Mandiri Gelombang II Politeknik Keselamatan Transportasi Jalan (PKTJ) Tahun Akademik 2026/2027 sebagaimana tercantum dalam Pengumuman Nomor PG-PKTJ 30 Tahun 2026. Masa pendaftaran yang semula berakhir pada tanggal 18 Juni 2026 diperpanjang sampai dengan tanggal 24 Juni 2026 pukul 23.59 WIB. Bagi calon peserta yang belum menyelesaikan proses pendaftaran, diimbau untuk segera melakukan pendaftaran dan melengkapi seluruh persyaratan yang telah ditentukan sebelum batas waktu yang ditetapkan.', `file_path` = 'https://pktj.ac.id/berita/20260618-1130-perpanjangan-masa-pendaftaran-sipencatar-jalur-mandiri-gelombang-ii-pktj-tahun-akademik-20262027', `file_name` = 'Informasi Selengkapnya', `tautan_links` = '[{\"url\": \"https://pktj.ac.id/berita/20260618-1130-perpanjangan-masa-pendaftaran-sipencatar-jalur-mandiri-gelombang-ii-pktj-tahun-akademik-20262027\", \"nama\": \"Informasi Selengkapnya\"}]', `tanggal` = '2026-06-18', `aktif` = 1, `updated_at` = NOW() WHERE `id` = 51;

INSERT INTO `daftar_informasis` (`judul_informasi`, `isi_informasi`, `kategori`, `tipe_informasi`, `file_informasi`, `tautan_links`, `aktif`, `pejabat_penguasa`, `penerbit_informasi`, `penanggung_jawab`, `bentuk_informasi`, `tempat_pembuatan`, `waktu_pembuatan`, `jangka_waktu`, `created_at`, `updated_at`) VALUES ('Perpanjangan Masa Pendaftaran SIPENCATAR Jalur Mandiri Gelombang II PKTJ Tahun Akademik 2026/2027', 'Informasi mengenai perpanjangan masa pendaftaran Seleksi Penerimaan Calon Taruna (SIPENCATAR) Jalur Mandiri Gelombang II Politeknik Keselamatan Transportasi Jalan (PKTJ) Tahun Akademik 2026/2027 sebagaimana tercantum dalam Pengumuman Nomor PG-PKTJ 30 Tahun 2026. Masa pendaftaran yang semula berakhir pada tanggal 18 Juni 2026 diperpanjang sampai dengan tanggal 24 Juni 2026 pukul 23.59 WIB. Bagi calon peserta yang belum menyelesaikan proses pendaftaran, diimbau untuk segera melakukan pendaftaran dan melengkapi seluruh persyaratan yang telah ditentukan sebelum batas waktu yang ditetapkan.', 'informasi-serta-merta', 'serta-merta', 'https://pktj.ac.id/berita/20260618-1130-perpanjangan-masa-pendaftaran-sipencatar-jalur-mandiri-gelombang-ii-pktj-tahun-akademik-20262027', '[{\"url\": \"https://pktj.ac.id/berita/20260618-1130-perpanjangan-masa-pendaftaran-sipencatar-jalur-mandiri-gelombang-ii-pktj-tahun-akademik-20262027\", \"nama\": \"Informasi Selengkapnya\"}]', 1, 'PPID Pelaksana UPT PKTJ Tegal', 'Bagian Keuangan dan Umum', 'Bagian Keuangan dan Umum', 'Softcopy & Website', 'Tegal', '2026', 'Selamanya', NOW(), NOW()) ON DUPLICATE KEY UPDATE `isi_informasi` = VALUES(`isi_informasi`), `file_informasi` = VALUES(`file_informasi`), `tautan_links` = VALUES(`tautan_links`), `aktif` = 1, `updated_at` = NOW();

UPDATE `informasi_sertamertas` SET `judul` = 'Imbauan Cetak Ulang Kartu Peserta Seleksi Kompetensi Dasar (SKD) SIPENCATAR Pola Pembibitan Tahun Akademik 2026/2027', `deskripsi` = 'Informasi mengenai pembaruan data pada Kartu Peserta Seleksi Kompetensi Dasar (SKD) SIPENCATAR Pola Pembibitan Kementerian Perhubungan Tahun Akademik 2026/2027. Sehubungan dengan adanya penyesuaian informasi jadwal pelaksanaan SKD pada beberapa kartu peserta, seluruh peserta diimbau untuk mencetak ulang Kartu Peserta SKD melalui akun masing-masing pada portal pendaftaran. Peserta diminta memastikan kembali kesesuaian informasi pada kartu terbaru, meliputi tanggal pelaksanaan SKD, lokasi pelaksanaan SKD, serta waktu atau sesi pelaksanaan SKD. Kartu peserta yang telah diperbarui wajib dibawa dan ditunjukkan pada saat pelaksanaan SKD sesuai dengan jadwal yang tercantum pada kartu peserta terbaru. Pengumuman selengkapnya dapat diakses melalui https://sipencatar.kemenhub.go.id/ dan https://sscasn.bkn.go.id/.', `file_path` = 'https://pktj.ac.id/berita/20260919-1225-peserta-sipencatar-diimbau-cetak-ulang-kartu-peserta-skd-tahun-akademik-20262027', `file_name` = 'Informasi Selengkapnya', `tautan_links` = '[{\"url\": \"https://pktj.ac.id/berita/20260919-1225-peserta-sipencatar-diimbau-cetak-ulang-kartu-peserta-skd-tahun-akademik-20262027\", \"nama\": \"Informasi Selengkapnya\"}]', `tanggal` = '2026-09-19', `aktif` = 1, `updated_at` = NOW() WHERE `id` = 52;

INSERT INTO `daftar_informasis` (`judul_informasi`, `isi_informasi`, `kategori`, `tipe_informasi`, `file_informasi`, `tautan_links`, `aktif`, `pejabat_penguasa`, `penerbit_informasi`, `penanggung_jawab`, `bentuk_informasi`, `tempat_pembuatan`, `waktu_pembuatan`, `jangka_waktu`, `created_at`, `updated_at`) VALUES ('Imbauan Cetak Ulang Kartu Peserta Seleksi Kompetensi Dasar (SKD) SIPENCATAR Pola Pembibitan Tahun Akademik 2026/2027', 'Informasi mengenai pembaruan data pada Kartu Peserta Seleksi Kompetensi Dasar (SKD) SIPENCATAR Pola Pembibitan Kementerian Perhubungan Tahun Akademik 2026/2027. Sehubungan dengan adanya penyesuaian informasi jadwal pelaksanaan SKD pada beberapa kartu peserta, seluruh peserta diimbau untuk mencetak ulang Kartu Peserta SKD melalui akun masing-masing pada portal pendaftaran. Peserta diminta memastikan kembali kesesuaian informasi pada kartu terbaru, meliputi tanggal pelaksanaan SKD, lokasi pelaksanaan SKD, serta waktu atau sesi pelaksanaan SKD. Kartu peserta yang telah diperbarui wajib dibawa dan ditunjukkan pada saat pelaksanaan SKD sesuai dengan jadwal yang tercantum pada kartu peserta terbaru. Pengumuman selengkapnya dapat diakses melalui https://sipencatar.kemenhub.go.id/ dan https://sscasn.bkn.go.id/.', 'informasi-serta-merta', 'serta-merta', 'https://pktj.ac.id/berita/20260919-1225-peserta-sipencatar-diimbau-cetak-ulang-kartu-peserta-skd-tahun-akademik-20262027', '[{\"url\": \"https://pktj.ac.id/berita/20260919-1225-peserta-sipencatar-diimbau-cetak-ulang-kartu-peserta-skd-tahun-akademik-20262027\", \"nama\": \"Informasi Selengkapnya\"}]', 1, 'PPID Pelaksana UPT PKTJ Tegal', 'Bagian Keuangan dan Umum', 'Bagian Keuangan dan Umum', 'Softcopy & Website', 'Tegal', '2026', 'Selamanya', NOW(), NOW()) ON DUPLICATE KEY UPDATE `isi_informasi` = VALUES(`isi_informasi`), `file_informasi` = VALUES(`file_informasi`), `tautan_links` = VALUES(`tautan_links`), `aktif` = 1, `updated_at` = NOW();

UPDATE `informasi_sertamertas` SET `judul` = 'Pemberitahuan Potensi Kepadatan Lalu Lintas Kegiatan Transjaya Run 2026 di Kawasan Jalan Semeru Kota Tegal', `deskripsi` = 'Informasi mengenai imbauan kepada warga masyarakat Kota Tegal, khususnya pengguna jalan di Kawasan Jalan Semeru, sehubungan dengan penyelenggaraan kegiatan Transjaya Run 2026 pada hari Minggu, 24 Mei 2026, pukul 05.00 s.d. 10.00 WIB. Guna mengantisipasi kepadatan arus lalu lintas, seluruh pengguna jalan diimbau untuk tetap berhati-hati, mengurangi kecepatan berkendara, dan mengutamakan keselamatan. Panitia Transjaya Run 2026 menyampaikan permohonan maaf atas ketidaknyamanan perjalanan yang mungkin timbul akibat potensi kepadatan tersebut, serta ucapan terima kasih atas perhatian, dukungan, dan kerja sama seluruh pihak.', `file_path` = 'https://www.instagram.com/p/DYrb10MlHfY/?utm_source=ig_web_copy_link&stkn=NTc4MTIwNjQ2YQ==', `file_name` = 'Informasi Selengkapnya', `tautan_links` = '[{\"url\": \"https://www.instagram.com/p/DYrb10MlHfY/?utm_source=ig_web_copy_link&stkn=NTc4MTIwNjQ2YQ==\", \"nama\": \"Informasi Selengkapnya\"}]', `tanggal` = '2026-05-24', `aktif` = 1, `updated_at` = NOW() WHERE `id` = 53;

INSERT INTO `daftar_informasis` (`judul_informasi`, `isi_informasi`, `kategori`, `tipe_informasi`, `file_informasi`, `tautan_links`, `aktif`, `pejabat_penguasa`, `penerbit_informasi`, `penanggung_jawab`, `bentuk_informasi`, `tempat_pembuatan`, `waktu_pembuatan`, `jangka_waktu`, `created_at`, `updated_at`) VALUES ('Pemberitahuan Potensi Kepadatan Lalu Lintas Kegiatan Transjaya Run 2026 di Kawasan Jalan Semeru Kota Tegal', 'Informasi mengenai imbauan kepada warga masyarakat Kota Tegal, khususnya pengguna jalan di Kawasan Jalan Semeru, sehubungan dengan penyelenggaraan kegiatan Transjaya Run 2026 pada hari Minggu, 24 Mei 2026, pukul 05.00 s.d. 10.00 WIB. Guna mengantisipasi kepadatan arus lalu lintas, seluruh pengguna jalan diimbau untuk tetap berhati-hati, mengurangi kecepatan berkendara, dan mengutamakan keselamatan. Panitia Transjaya Run 2026 menyampaikan permohonan maaf atas ketidaknyamanan perjalanan yang mungkin timbul akibat potensi kepadatan tersebut, serta ucapan terima kasih atas perhatian, dukungan, dan kerja sama seluruh pihak.', 'informasi-serta-merta', 'serta-merta', 'https://www.instagram.com/p/DYrb10MlHfY/?utm_source=ig_web_copy_link&stkn=NTc4MTIwNjQ2YQ==', '[{\"url\": \"https://www.instagram.com/p/DYrb10MlHfY/?utm_source=ig_web_copy_link&stkn=NTc4MTIwNjQ2YQ==\", \"nama\": \"Informasi Selengkapnya\"}]', 1, 'PPID Pelaksana UPT PKTJ Tegal', 'Bagian Keuangan dan Umum', 'Bagian Keuangan dan Umum', 'Softcopy & Website', 'Tegal', '2026', 'Selamanya', NOW(), NOW()) ON DUPLICATE KEY UPDATE `isi_informasi` = VALUES(`isi_informasi`), `file_informasi` = VALUES(`file_informasi`), `tautan_links` = VALUES(`tautan_links`), `aktif` = 1, `updated_at` = NOW();
